import React, { Fragment } from 'react';

import { Icon } from '@hexa-ui/components2';
import { Close } from '@hexa-ui/icons2';
import { Skeleton } from 'components/Skeleton';

import {
  StyledBreadcrumbContainer,
  StyledChip,
  StyledChipLabel,
  StyledCloseButton,
  StyledSeparator,
} from './BreadcrumbChips.styles';
import { BreadcrumbSeparatorIcon } from './BreadcrumbSeparatorIcon';

interface BreadcrumbChipsProps {
  path: string[];
  rootLabel: string;
  viewByLabel?: string;
  onGoToStep: (pathIndex: number) => void;
  isLoading?: boolean;
  dataTestId?: string;
}

export function BreadcrumbChips({
  path,
  rootLabel,
  viewByLabel,
  onGoToStep,
  isLoading,
  dataTestId,
}: Readonly<BreadcrumbChipsProps>): JSX.Element {
  const baseTestId = dataTestId ?? 'breadcrumb-chips';
  const isRootOnly = path.length === 0;

  if (isLoading) {
    return (
      <StyledBreadcrumbContainer data-testid={`${baseTestId}-skeleton`}>
        <Skeleton
          height="30px"
          width="90px"
          length={3}
          borderRadius="x-large"
          gap="small"
        />
      </StyledBreadcrumbContainer>
    );
  }

  return (
    <StyledBreadcrumbContainer data-testid={baseTestId}>
      <StyledChip
        isHighlighted={isRootOnly}
        isInteractive={!isRootOnly}
        title={rootLabel}
        data-testid={`${baseTestId}-chip-root`}
        onClick={() => {
          if (isRootOnly) return;
          onGoToStep(-1);
        }}
      >
        <StyledChipLabel>{rootLabel}</StyledChipLabel>
      </StyledChip>

      {viewByLabel && (
        <>
          <StyledSeparator data-testid={`${baseTestId}-separator-view-by`}>
            <BreadcrumbSeparatorIcon />
          </StyledSeparator>

          <StyledChip
            isHighlighted={false}
            title={viewByLabel}
            data-testid={`${baseTestId}-chip-view-by`}
          >
            <StyledChipLabel>{viewByLabel}</StyledChipLabel>
          </StyledChip>
        </>
      )}

      {path.map((label, index) => {
        const isLast = index === path.length - 1;

        return (
          <Fragment key={label + index}>
            <StyledSeparator data-testid={`${baseTestId}-separator`}>
              <BreadcrumbSeparatorIcon />
            </StyledSeparator>

            <StyledChip
              isHighlighted={isLast}
              isInteractive={!isLast}
              title={label}
              data-testid={`${baseTestId}-chip-${index}`}
              onClick={() => {
                if (isLast) return;
                onGoToStep(index);
              }}
            >
              <StyledChipLabel>{label}</StyledChipLabel>

              {isLast && (
                <StyledCloseButton
                  type="button"
                  onClick={() => onGoToStep(path.length - 2)}
                  aria-label={`Remove ${label} filter`}
                  data-testid={`${baseTestId}-close`}
                >
                  <Icon icon={Close} size="small" color="#141414" />
                </StyledCloseButton>
              )}
            </StyledChip>
          </Fragment>
        );
      })}
    </StyledBreadcrumbContainer>
  );
}
